import java.util.*;
import java.io.*;

public class Main {
    static final int MAXN = 66;
    static int r, c, n;
    static String s;
    static long[][] comb = new long[MAXN][MAXN];
    static int[] countA = new int[MAXN], countB = new int[MAXN];
    static List<Long>[] partials = new ArrayList[MAXN], partials_zero = new ArrayList[MAXN];

    static {
        for (int i = 0; i < MAXN; i++) {
            partials[i] = new ArrayList<>();
            partials_zero[i] = new ArrayList<>();
        }
    }

    static void prepare_combinations() {
        for (int i = 0; i <= n; ++i) {
            comb[i][0] = 1;
            for (int j = 1; j <= i; ++j)
                comb[i][j] = comb[i - 1][j - 1] + comb[i - 1][j];
        }
    }

    static long calc_dif(int conf, int a_prev, int b_prev) {
        long total = 0;
        for (int i = 0; i <= c; ++i) {
            if ((conf & (1 << i)) != 0) {
                b_prev++;
                total -= comb[b_prev - 1][r - 1] * (comb[n - b_prev][r] - comb[a_prev][r]);
            } else {
                a_prev++;
                total += comb[a_prev - 1][r - 1] * (comb[n - a_prev][r] - comb[b_prev][r]);
            }
        }
        return total;
    }

    static boolean valid_conf(int conf) {
        for (int i = 0; i <= c; ++i) {
            char ch = s.charAt(2 * r + c + i);
            if (ch == 'A' && ((conf >> i) & 1) == 1) return false;
            if (ch == 'B' && ((conf >> i) & 1) == 0) return false;
        }
        return true;
    }

    static void process_second() {
        int total_conf = 1 << (c + 1);
        for (int conf = 0; conf < total_conf; ++conf) {
            int b_count = Integer.bitCount(conf);
            int a_count = c + 1 - b_count;
            if (valid_conf(conf))
                partials[a_count].add(calc_dif(conf, r + c - a_count, r + c - b_count));
            else
                partials_zero[a_count].add(calc_dif(conf, r + c - a_count, r + c - b_count));
        }
        for (int i = 0; i <= c + 1; ++i) {
            Collections.sort(partials[i]);
            Collections.sort(partials_zero[i]);
        }
    }

    static long get_coef(int conf) {
        int i;
        for (i = 0; i <= c; ++i) {
            if ( (((conf >> i) & 1) != (conf & 1)) ) break;
        }
        for (int j = i; j <= c; ++j) {
            char ch = s.charAt(2 * r - 1 + j);
            if (ch == 'A' && (((conf >> j) & 1) == 1)) return 0;
            if (ch == 'B' && (((conf >> j) & 1) == 0)) return 0;
        }
        int setA = r - 1 + (((conf & 1) == 0) ? i : 0);
        int setB = r - 1 + (((conf & 1) == 1) ? i : 0);
        if (setA < countA[2 * r - 2 + i]) return 0;
        if (setB < countB[2 * r - 2 + i]) return 0;
        int total = setA + setB - countA[2 * r - 2 + i] - countB[2 * r - 2 + i];
        int choose = setA - countA[2 * r - 2 + i];
        return comb[total][choose];
    }

    static void update_answer(long[] ans, long[] act) {
        if (act[0] < 0) act[0] = -act[0];
        if (ans[0] > act[0]) {
            ans[0] = act[0];
            ans[1] = act[1];
        } else if (ans[0] == act[0]) {
            ans[1] += act[1];
        }
    }

    static long count_occurrences(List<Long> data, long val) {
        int low = Collections.binarySearch(data, val);
        if (low < 0) low = -low - 1;
        int up = Collections.binarySearch(data, val);
        if (up < 0) up = -up - 1;
        else {
            while (up < data.size() && data.get(up) == val) up++;
        }
        return up - low;
    }

    static long main_compute() {
        int total_conf = 1 << (c + 1);
        long[] answer = {Long.MAX_VALUE, 0};
        for (int conf = 0; conf < total_conf; ++conf) {
            int b_count = Integer.bitCount(conf);
            int a_count = c + 1 - b_count;
            long act = calc_dif(conf, r - 1, r - 1);
            long coef = get_coef(conf);
            List<Long> arr = partials[c + 1 - a_count];
            int idx = Collections.binarySearch(arr, -act);
            if (idx < 0) idx = -idx - 1;
            else {
                // exact match
            }
            if (idx < arr.size()) {
                long val = arr.get(idx);
                if (answer[0] >= Math.abs(val + act)) {
                    long count = count_occurrences(arr, val);
                    update_answer(answer, new long[]{Math.abs(val + act), coef * count});
                }
            }
            if (idx > 0) {
                long val = arr.get(idx - 1);
                if (answer[0] >= Math.abs(val + act)) {
                    long count = count_occurrences(arr, val);
                    update_answer(answer, new long[]{Math.abs(val + act), coef * count});
                }
            }
            long zero_coef = 0;
            List<Long> arr_zero = partials_zero[c + 1 - a_count];
            int idx_zero = Collections.binarySearch(arr_zero, -act);
            if (idx_zero < 0) idx_zero = -idx_zero - 1;
            else {
                // exact match
            }
            if (idx_zero < arr_zero.size()) {
                long val = arr_zero.get(idx_zero);
                long count = count_occurrences(arr, val);
                if (answer[0] >= Math.abs(val + act))
                    update_answer(answer, new long[]{Math.abs(val + act), zero_coef * count});
            }
            if (idx_zero > 0) {
                long val = arr_zero.get(idx_zero - 1);
                long count = count_occurrences(arr, val);
                if (answer[0] >= Math.abs(val + act))
                    update_answer(answer, new long[]{Math.abs(val + act), zero_coef * count});
            }
        }
        return answer[1];
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        r = Integer.parseInt(st.nextToken());
        c = Integer.parseInt(st.nextToken());
        s = br.readLine();
        n = 2 * (r + c);
        prepare_combinations();
        for (int i = 1; i <= n; ++i) {
            countA[i] = countA[i - 1] + (s.charAt(i - 1) == 'A' ? 1 : 0);
            countB[i] = countB[i - 1] + (s.charAt(i - 1) == 'B' ? 1 : 0);
        }
        process_second();
        System.out.println(main_compute());
    }
